/**
 * Model declarations live in `./models/index` (generated by the declarations
 * task as `export const all: ModelDeclaration[]`). Loading is dynamic so the
 * adapter still compiles and loads before those files land; the empty array is
 * the documented fallback. No files under `src/models/**` are written here.
 */
import type { ModelDeclaration } from '@modelbay/core'

async function loadAll(): Promise<ModelDeclaration[]> {
  // 变量 specifier：生成前 TypeScript 不会因缺少模块报错；三条路径分别覆盖
  // vitest 源码解析与 vp pack 产出的 .mjs 布局。
  const candidates = ['./models/index', './models/index.js', './models/index.mjs']
  for (const specifier of candidates) {
    try {
      const module = await import(/* @vite-ignore */ specifier)
      const all = (module as { all?: unknown }).all
      if (Array.isArray(all)) return all as ModelDeclaration[]
    } catch {
      // 继续尝试下一个候选路径
    }
  }
  return []
}

/** All declared models for the Ark channels; empty until declarations land. */
export const all: ModelDeclaration[] = await loadAll()
